//! Rapid7 Recog banner fingerprints — auto-generated.
//!
//! Source: <https://github.com/rapid7/recog> commit d3d20938da9f5f1e442c2419fe6c30cd651b6878 2026-08-17
//! Licence: BSD-2-Clause, "Copyright (c) 2014-2015, Rapid7". The copyright
//! notice, the conditions and the disclaimer it requires are reproduced verbatim
//! in THIRD-PARTY-NOTICES.md at the repository root.
//!
//! Imported: 2430 fingerprints across 13 match keys, 4529 upstream examples (test-only).
//!
//! Only fingerprint files whose input this workspace already reads off the wire
//! are imported, and only the parameters something here consumes; a fingerprint
//! left with no consumed parameter is dropped (34 of them, mostly
//! `html_title`'s generic error pages). `scripts/gen_recog_db.py` names every
//! upstream file it refused and why.
//!
//! Row order is upstream file order and is load-bearing: Recog resolves a string
//! against the first pattern that matches, so the table must not be sorted.
//!
//! Regenerate with
//! `uv run --with defusedxml python scripts/gen_recog_db.py --clone <path>`,
//! then `cargo fmt`.

/// A fingerprint parameter this workspace consumes.
///
/// Recog defines many more; the rest are dropped at import.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum RecogField {
    /// Vendor of the listening software. Recog `service.vendor`.
    ServiceVendor,
    /// Name of the listening software. Recog `service.product`.
    ServiceProduct,
    /// Version of the listening software. Recog `service.version`.
    ServiceVersion,
    /// Product family of the listening software. Recog `service.family`.
    ServiceFamily,
    /// Vendor of the operating system or firmware. Recog `os.vendor`.
    OsVendor,
    /// Operating system or firmware name. Recog `os.product`.
    OsProduct,
    /// Operating system or firmware version. Recog `os.version`.
    OsVersion,
    /// Operating system family. Recog `os.family`.
    OsFamily,
    /// Upstream device-class vocabulary, e.g. `Printer`, `WAP`. Recog `os.device`.
    OsDevice,
    /// CPU architecture. Recog `os.arch`.
    OsArch,
    /// Hardware vendor. Recog `hw.vendor`.
    HwVendor,
    /// Hardware model. Recog `hw.product`.
    HwProduct,
    /// Hardware model number, where upstream separates it from `hw.product`. Recog `hw.model`.
    HwModel,
    /// Hardware product family. Recog `hw.family`.
    HwFamily,
    /// Hardware device class, same vocabulary as `os.device`. Recog `hw.device`.
    HwDevice,
    /// Hostname the service disclosed. Recog `host.name`.
    HostName,
}

impl RecogField {
    /// The Recog parameter name, e.g. `service.product`.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::ServiceVendor => "service.vendor",
            Self::ServiceProduct => "service.product",
            Self::ServiceVersion => "service.version",
            Self::ServiceFamily => "service.family",
            Self::OsVendor => "os.vendor",
            Self::OsProduct => "os.product",
            Self::OsVersion => "os.version",
            Self::OsFamily => "os.family",
            Self::OsDevice => "os.device",
            Self::OsArch => "os.arch",
            Self::HwVendor => "hw.vendor",
            Self::HwProduct => "hw.product",
            Self::HwModel => "hw.model",
            Self::HwFamily => "hw.family",
            Self::HwDevice => "hw.device",
            Self::HostName => "host.name",
        }
    }

    /// Every variant, in declaration order.
    pub const ALL: [Self; 16] = [
        Self::ServiceVendor,
        Self::ServiceProduct,
        Self::ServiceVersion,
        Self::ServiceFamily,
        Self::OsVendor,
        Self::OsProduct,
        Self::OsVersion,
        Self::OsFamily,
        Self::OsDevice,
        Self::OsArch,
        Self::HwVendor,
        Self::HwProduct,
        Self::HwModel,
        Self::HwFamily,
        Self::HwDevice,
        Self::HostName,
    ];
}

/// One parameter of one fingerprint.
#[derive(Debug, Clone, Copy)]
pub struct RecogParam {
    /// Field this parameter sets.
    pub field: RecogField,
    /// Capture group to read, or 0 when [`Self::value`] is literal.
    pub pos: u8,
    /// Literal value when `pos == 0`; may interpolate `{field.name}`.
    pub value: &'static str,
}

/// One Recog fingerprint: a pattern and what a match asserts.
#[derive(Debug, Clone, Copy)]
pub struct RecogFingerprint {
    /// Rust-dialect pattern, inline flags already applied.
    pub pattern: &'static str,
    /// Upstream description.
    pub description: &'static str,
    /// Parameters a match yields.
    pub params: &'static [RecogParam],
}

/// A match key: one kind of string, one fingerprint table.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum RecogKey {
    /// Recog `ssh.banner` — `services.rs`: the software-and-comment part of an RFC 4253 identification string.
    SshBanner,
    /// Recog `telnet.banner` — `services.rs`: the TCP/23 banner.
    TelnetBanner,
    /// Recog `ftp.banner` — `services.rs`: the TCP/21 greeting.
    FtpBanner,
    /// Recog `smtp.banner` — `services.rs`: the TCP/25 greeting.
    SmtpBanner,
    /// Recog `imap4.banner` — `services.rs`: the TCP/143 greeting.
    ImapBanner,
    /// Recog `pop3.banner` — `services.rs`: the TCP/110 greeting.
    PopBanner,
    /// Recog `http_header.server` — services.rs and `http_audit.rs`: the `Server` response header.
    HttpServer,
    /// Recog `http_header.wwwauth` — `http_audit.rs`: the `WWW-Authenticate` response header.
    HttpWwwAuth,
    /// Recog `html_title` — `http_audit.rs`: the `<title>` of an unauthenticated GET.
    HtmlTitle,
    /// Recog `snmp.sys_description` — `snmp.rs`: `sysDescr.0` from a v2c `GetRequest`.
    SnmpSysDescr,
    /// Recog `x509.subject` — `ssl.rs`: the certificate subject, rendered as a Go-style RDN string.
    X509Subject,
    /// Recog `x509.issuer` — `ssl.rs`: the certificate issuer, rendered as a Go-style RDN string.
    X509Issuer,
    /// Recog `hp.pjl.id` — `printers.rs`: the `@PJL INFO ID` response from TCP/9100.
    HpPjlId,
}

